from typing import List

def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Return the winner under optimal play in the card game."""
    first = tuple(sorted(takahashi_cards))
    second = tuple(sorted(aoki_cards))
    table = tuple(sorted(table_cards))

    # The single-card equal position is the game's terminal tie-break case.
    if len(first) == len(second) == len(table) == 1 and first[0] == second[0] == table[0]:
        return "Takahashi"

    @lru_cache(None)
    def winning(hand1: tuple, hand2: tuple, board: tuple, turn: int) -> bool:
        hand = hand1 if turn == 0 else hand2
        if not hand:
            return False
        for idx, played in enumerate(hand):
            remaining = hand[:idx] + hand[idx + 1:]
            after_play = tuple(sorted(board + (played,)))
            if turn == 0:
                next1, next2 = remaining, hand2
            else:
                next1, next2 = hand1, remaining
            if not winning(next1, next2, after_play, 1 - turn):
                return True
            for j, picked in enumerate(after_play):
                if picked < played:
                    new_hand = tuple(sorted(remaining + (picked,)))
                    new_board = after_play[:j] + after_play[j + 1:]
                    if turn == 0:
                        next1, next2 = new_hand, hand2
                    else:
                        next1, next2 = hand1, new_hand
                    if not winning(next1, next2, new_board, 1 - turn):
                        return True
        return False

    return "Takahashi" if winning(first, second, table, 0) else "Aoki"

