from functools import lru_cache


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count numbers whose digit product is divisible by their digit sum."""
    def count_up_to(n: int) -> int:
        if n <= 0:
            return 0
        digits = tuple(map(int, str(n)))
        length = len(digits)
        answer = 0

        # Fixing the final digit sum lets us track the product modulo that sum.
        for target_sum in range(1, 9 * length + 1):
            @lru_cache(maxsize=None)
            def visit(pos: int, digit_sum: int, product_mod: int, started: bool, tight: bool) -> int:
                if digit_sum > target_sum:
                    return 0
                if digit_sum + 9 * (length - pos) < target_sum:
                    return 0
                if pos == length:
                    return int(digit_sum == target_sum and product_mod == 0 and started)

                limit = digits[pos] if tight else 9
                ways = 0
                for digit in range(limit + 1):
                    next_started = started or digit != 0
                    next_sum = digit_sum + (digit if next_started else 0)
                    if next_started:
                        next_mod = (product_mod * digit) % target_sum if started else digit % target_sum
                    else:
                        next_mod = 1 % target_sum
                    ways += visit(
                        pos + 1,
                        next_sum,
                        next_mod,
                        next_started,
                        tight and digit == limit,
                    )
                return ways

            answer += visit(0, 0, 1 % target_sum, False, True)
        return answer

    return count_up_to(r) - count_up_to(l - 1)

