        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if not (imin <= ni <= imax and jmin <= nj <= jmax):
                continue
            if h:
                if di:
                    yield (ni, nj, 0 if di > 0 else K - 1), 1
                elif k == (K - 1 if dj > 0 else 0):
                    for q in indices:
                        yield (ni, nj, q), 1
            else:
                if dj:
                    yield (ni, nj, 0 if dj > 0 else K - 1), 1
                elif k == (K - 1 if di > 0 else 0):
                    for q in indices:
                        yield (ni, nj, q), 1

    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, u = heappop(heap)
        if d != dist[u]:
            continue
        if u == goal:
            return d
        for v, w in edges(u):
            nd = d + w
            if nd < dist.get(v, 10**100):
                dist[v] = nd
                heappush(heap, (nd, v))
    return abs(dx) + abs(dy)

